(7762823, 1286510, 83313, '<td valign="top">Cute bunny. Love the expression. Appropriate title! The bright colors behind him (her?) grab my eye and pull it away from the main subject.</td>', 'Cute bunny. Love the expression. Appropriate title! The bright colors behind him (her?) grab my eye and pull it away from the main subject.', '2024-01-31 00:25:42.000000', NULL, 1),
(7762826, 1286482, 83313, '<td valign="top">The motion blur on the pencil keeps me from being able to give this a high end vote. But a great idea.</td>', 'The motion blur on the pencil keeps me from being able to give this a high end vote. But a great idea.', '2024-01-31 00:27:56.000000', NULL, 1),
(7762834, 1286475, 114285, '<td valign="top">Ohhh lovely shot.</td>', 'Ohhh lovely shot.', '2024-01-31 02:22:01.000000', NULL, 1),
(7762842, 1286510, 65234, '<td valign="top">OMG, that rabbit is simply adorable. I love the perspective and the rabbit''s expression. But then I really miss having my own bunnies so I may be biased :-)</td>', 'OMG, that rabbit is simply adorable. I love the perspective and the rabbit''s expression. But then I really miss having my own bunnies so I may be biased :-)', '2024-01-31 07:33:32.000000', NULL, 1),
(7762844, 1286440, 65234, '<td valign="top">It''s purple!</td>', 'It''s purple!', '2024-01-31 07:34:01.000000', NULL, 1),
(7762845, 1286428, 65234, '<td valign="top">Nice leaf structure. I love all the curls.</td>', 'Nice leaf structure. I love all the curls.', '2024-01-31 07:35:15.000000', NULL, 1),
(7762846, 1286490, 141319, '<td valign="top">Nice image, but doesn''t really show the shallow DOF IMO. The whole foreground is in focus</td>', 'Nice image, but doesn''t really show the shallow DOF IMO. The whole foreground is in focus', '2024-01-31 07:36:25.000000', NULL, 1),
(7762847, 1286316, 141319, '<td valign="top">I find the green leaf across the flower distracting. Also, for this challenge, you left a LOT of stuff in, or almost in focus (leaf edge, bee and flower. I would have scored this higher if you had focused on only 1 subject</td>', 'I find the green leaf across the flower distracting. Also, for this challenge, you left a LOT of stuff in, or almost in focus (leaf edge, bee and flower. I would have scored this higher if you had focused on only 1 subject', '2024-01-31 07:38:15.000000', NULL, 1),
(7762848, 1286507, 141319, '<td valign="top">Nice composition. The focus is on the sleeve. This image would have scored better from me had you chosen the peel as your focus point.</td>', 'Nice composition. The focus is on the sleeve. This image would have scored better from me had you chosen the peel as your focus point.', '2024-01-31 07:39:13.000000', NULL, 1),
(7762849, 1286436, 141319, '<td valign="top">Of course - it had to be :-). Super image, and the fact that the whole width of the blade of grass is in focus I think is brilliant.</td>', 'Of course - it had to be :-). Super image, and the fact that the whole width of the blade of grass is in focus I think is brilliant.', '2024-01-31 07:40:07.000000', NULL, 1),
